$(document).ready(function () {
    $("#search-box-container-main").load('/search_box.bc')
});

//<!---------------JS MENU RESPONSIVE--------------->//
var menu = new MmenuLight(
    document.querySelector('#menu'),
    'all'
);
var navigator = menu.navigation({
    selectedClass: 'Selected',
    slidingSubmenus: true,
    theme: 'light',
    title: ''
});

var drawer = menu.offcanvas({
    position: 'right'
});

document.querySelector('a[href="#menu"]')
    .addEventListener('click', evnt => {
        evnt.preventDefault();
        drawer.open();
    });
$("#back-to-top").on("click", function (e) {
    $("html, body").animate({
        scrollTop: 0
    }, 600);
    return false;
});
//<!---------------JS LOGIN--------------->//
$(document).ready(function (e) {
    if ($(window).width() <= 1200) {
        $(".loginRegister").load("/M_Login_Register.bc")
        $(".col2-mobile-header").load('/M_Login_Information.bc')
    } else {
        $(".Login_Information").load("/Client_Login_Information_ver.2.bc")
    }
});
//----------------JS TOUR ARTICLE LIST----------------//
$(".item_hotel-content").each(function () {
    for (var i = 0; i < $(this).find(".rate-hotel-value").val(); i++) {
        $(this).find(".rate-hotel").append('<i class="fa fa-star"></i>')
    }
})
$(".text-limit").each(function () {
    if ($(this).text().length > 200) {
        $(this).text($(this).text().substr(0, 200) + '...')
    }
})
$(".mini-about").each(function () {
    if ($(this).text().length > 170) {
        $(this).text($(this).text().substr(0, 170) + '...')
    }
})
$(".slice").each(function () {
    if ($(this).text().charAt(0) == ',') {
        $(this).text($(this).text().substring(1))
        $(this).text($(this).text().replace(/(\d)(?=(\d\d\d)+(?!\d))/g, "$1,"));
    }
})
//----------------JS QUESTION/ANSWER----------------//
function toggle_answer(element) {
    $(element).closest("li").toggleClass('active')
    if ($(element).closest("li").find(".question-icon").hasClass('fa-plus')) {
        $(element).closest("li").find(".question-icon").removeClass("fa-plus")
        $(element).closest("li").find(".question-icon").addClass("fa-minus")
    } else {
        $(element).closest("li").find(".question-icon").addClass("fa-plus")
        $(element).closest("li").find(".question-icon").removeClass("fa-minus")
    }
    $(element).closest("li").find(".faq-a").toggleClass("unvisible")

}

function select_faq_nav(element, id) {
    $(`#${id}`).removeClass('unvisible')
    $(element).addClass('active')
    $(element).siblings().removeClass('active')
    $(`#${id}`).siblings().addClass('unvisible')
}
//----------------JS TOUR ARTICLE LIST----------------//
function refresh_captcha(element, event) {
    $(element).closest("form").find(".load-captcha").load("/Client_Captcha.bc");
   }
   /*------------------SUBMIT FORM-----------------------*/
  $(".form-content").submit(function (e) {
    var self = $(this);
    self.closest("form").find(".Loading_Form").show();
    e.preventDefault();
    $.ajax({
    url: self.attr("action"),
    type: self.attr("method"),
    data: $(self).serialize(),
    success: function (response) {
    self.closest("form").find(".Loading_Form").hide();
    self.closest("form").find(".Message-Form").empty().show().html(response);
    },
    });
  });